import ast,json,subprocess
from pathlib import Path
runtime=json.loads(subprocess.check_output(['python3','tools.py','resolve','run://r-001']))
p=json.loads(Path('proposal.json').read_text())
schema=runtime['study_schema']
def validate(value,s,path='"'$'"'):
 typ=s.get('type')
 if typ:
  ok={'object':lambda x:isinstance(x,dict),'array':lambda x:isinstance(x,list),'string':lambda x:isinstance(x,str),'boolean':lambda x:isinstance(x,bool),'number':lambda x:isinstance(x,(int,float)) and not isinstance(x,bool),'integer':lambda x:isinstance(x,int) and not isinstance(x,bool)}[typ](value)
  assert ok,(path,typ,type(value).__name__)
 if 'enum' in s:assert value in s['enum'],(path,'enum')
 if 'const' in s:assert value==s['const'],(path,'const')
 if isinstance(value,dict):
  assert all(k in value for k in s.get('required',[])),(path,'missing required')
  if s.get('additionalProperties') is False:assert set(value)<=set(s.get('properties',{})),(path,'unknown field')
  for k,v in value.items():
   if k in s.get('properties',{}):validate(v,s['properties'][k],path+'.'+k)
 if isinstance(value,list):
  assert len(value)>=s.get('minItems',0),(path,'minItems')
  for i,v in enumerate(value):validate(v,s.get('items',{}),path+f'[{i}]')
 if isinstance(value,str):assert len(value)>=s.get('minLength',0),(path,'minLength')
validate(p['study'],schema)
assert p['study']['protocol_ref']==runtime['required_study_protocol_ref']
allowed=set(runtime['context']['allowed_observation_ids'])
assert set(p['study']['evidence_refs'])<=allowed
assert p['parent_trial'] in allowed
assert 1<=len(p['variants'])<=4 and any(v['role']=='candidate' for v in p['variants'])
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert len({v['file'] for v in p['variants']})==len(p['variants'])
for v in p['variants']:
 assert Path(v['file']).name==v['file'] and v['file'].endswith('.py')
 t=ast.parse(Path(v['file']).read_text())
 c=ast.literal_eval(next(n.value for n in t.body if isinstance(n,ast.Assign) and any(isinstance(a,ast.Name) and a.id=='CONFIG' for a in n.targets)))
 assert c==v['config']
 assert v['role'] in ['candidate','control']
# A literal configuration factorial with exactly two changed dimensions.
configs=[v['config'] for v in p['variants']]
for k in configs[0]:
 if k not in ['primary_adapter_readout','primary_residual_hidden']:assert len({repr(c[k]) for c in configs})==1,k
assert {(c['primary_adapter_readout'],c['primary_residual_hidden']) for c in configs}=={('even',16),('signed',16),('even',64),('signed',64)}
for a in p['knowledge_assessments']:
 assert a['decision'] in ['used','considered','rejected','unresolved']
 assert set(a['variant_names'])<={v['name'] for v in p['variants']}
print('Study schema, evidence lineage, protocol identity, files, configs, four factorial cells and knowledge assessments: PASS')
print('Authoritative host validator/native checks are not available locally; no training launched.')
PY"

